// Root inputs of the motion offset root, taken from the offline replay of a recorded 60 fps play (2026-11-14): per row dt, capsule
// delta (current capsule axes, m), capsule yaw delta (rad), animation delta (previous visual axes, m), animation yaw delta (rad),
// movingGround, montage, and the offset the replay produced with the unbounded law (x, y, m). Seeds: the offset before the first row
// (x, y m, yaw rad).
#pragma once
struct RecordedRow
{
    float dt, capX, capY, capYaw, animX, animY, animYaw;
    int moving, montage;
    float recX, recY;
};
struct RecordedRoot
{
    float x, y, yaw;
};
